  1	import {createHash} from "node:crypto";
  2	
  3	import {buildDebtBalanceBridge, checkIdentity} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	import {referenceDataRegistry} from "../reference-data";
  8	
  9	/**
 10	 * Executor of the method `reconcile-financial-statements` (v5, after the fourth independent review).
 11	 * Proves that material numbers close between statements, notes and release, runs the identities
 12	 * through financial-core, and keeps every difference above the tolerance as an open divergence
 13	 * with its anchors. Two sources that disagree are never averaged and never silently resolved. Two
 14	 * sources are compared only when they count the same components at the same date; otherwise the
 15	 * pair is `not_comparable`, which is not `closes`. An explanation names the source it starts from
 16	 * and the source it reaches, with the sign preserved. A tolerance above zero exists only under a
 17	 * versioned policy, and policy metadata is checked even at zero. A single-source account is recorded,
 18	 * never compared. Inside an account that is not comparable as a whole, the sources that share a
 19	 * definition, components and date are compared among themselves, so a divergence between two
 20	 * carrying amounts is never lost behind a nominal or a fair value. Every component tag is a known
 21	 * tag the definition text names. Every calculation carries the anchors of its operands. An empty
 22	 * base blocks.
 23	 */
 24	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
 25	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 26	const nonEmpty = z.string().trim().min(1);
 27	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 28	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 29	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), table: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 30	type Anchor = z.infer<typeof anchorSchema>;
 31	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 32	
 33	const toleranceSchema = z.object({value: nonNegative, policyKey: nonEmpty.optional(), policyVersion: nonEmpty.optional()}).strict();
 34	/** A tolerance above zero must be the value the registered policy states for the family and the unit, at the policy's current version. */
 35	function tolerancePolicyIssue(family: string, tolerance: z.infer<typeof toleranceSchema>, unit: string): string | null {
 36	  const zero = new Decimal(tolerance.value).isZero();
 37	  if (zero && !tolerance.policyKey && !tolerance.policyVersion) return null;
 38	  if (!tolerance.policyKey || !tolerance.policyVersion) return zero ? `${family}: policy metadata must carry both policyKey and policyVersion, or neither` : `${family}: a tolerance above zero needs policyKey and policyVersion`;
 39	  const policy = referenceDataRegistry.find((entry) => entry.key === tolerance.policyKey);
 40	  if (!policy) return `${family}: policy ${tolerance.policyKey} is not in the reference-data registry`;
 41	  if (policy.version !== tolerance.policyVersion) return `${family}: policy ${tolerance.policyKey} is at version ${policy.version}, not ${tolerance.policyVersion}`;
 42	  if (zero) return null;
 43	  if (policy.status === "required_missing" || policy.value === null || typeof policy.value !== "object") return `${family}: policy ${tolerance.policyKey} has no value yet; a tolerance above zero cannot rest on it`;
 44	  const value = policy.value as {families?: Record<string, string>; familiesUnit?: string};
 45	  const allowed = value.families?.[family];
 46	  if (allowed === undefined) return `${family}: policy ${tolerance.policyKey} states no tolerance for this family`;
 47	  if (value.familiesUnit !== unit) return `${family}: policy ${tolerance.policyKey} states its tolerances in ${value.familiesUnit ?? "no unit"}, not ${unit}`;
