305	      uncovered.push({id: "interest_bridge", state: "insufficient_evidence", reason: `the note's figure counts ${left.components.join(", ")} and the income statement's counts ${right.components.join(", ")}; the difference of ${bridge.difference} is recorded, not bridged`});
306	    }
307	  } else absent("interest_bridge", "the interest expense bridge was not tested: the note's accrued interest or the income statement's expense is not in the base");
308	
309	  const openDivergences = [
310	    ...reconciliations.filter((entry) => entry.state === "open" || entry.state === "not_comparable").map((entry) => ({
311	      id: entry.id, label: entry.label,
312	      values: entry.values.filter((value) => entry.unexplained_sources.includes(value.source)).map((value) => ({source: value.source, value: value.value, anchor: value.anchor})),
313	      reason: entry.state === "not_comparable"
314	        ? `the sources are not comparable: ${entry.comparability.reasons.join("; ")}; carried as a divergence, no value chosen${entry.comparable_subsets.length > 0 ? `; among themselves, ${entry.comparable_subsets.map((subset) => `${subset.sources.join(" and ")} (${subset.definitionKey}) differ by ${subset.spread} and ${subset.state === "closes" ? "close" : "stay open"}`).join("; ")}` : ""}`
315	        : entry.explanations.length > 0 ? `the stated adjustments leave ${entry.unexplained_sources.join(", ")} unexplained${entry.explanations.filter((explanation) => !explanation.holds).map((explanation) => ` (from ${explanation.fromSource} to ${explanation.toSource}: residual ${explanation.residual})`).join("")}` : `sources differ by ${entry.spread} with no explanation in the base; carried as a divergence, no value chosen`,
316	    })),
317	    ...reconciliations.flatMap((entry) => entry.comparable_subsets.filter((subset) => subset.state === "open").map((subset) => ({
318	      id: `${entry.id}:${subset.definitionKey}`, label: `${entry.label} (${subset.definitionKey})`,
319	      values: entry.values.filter((value) => subset.sources.includes(value.source)).map((value) => ({source: value.source, value: value.value, anchor: value.anchor})),
320	      reason: `${subset.sources.join(" and ")} state the same thing (${subset.definitionKey}, ${subset.components.join("+")}, ${subset.asOf}) and differ by ${subset.spread}; carried as a divergence, no value chosen`,
321	    }))),
322	  ];
323	  const state: ReconciliationOutput["state"] = blockReasons.length > 0 ? "blocked"
324	    : identities.some((entry) => entry.state === "fails") ? "identity_failed"
325	    : incompleteReasons.length > 0 ? "incomplete"
326	    : openDivergences.length > 0 ? "open_divergences"
327	    : reconciliations.some((entry) => entry.state === "explained") ? "differences_explained" : "closes";
328	  const body = {
329	    schema_version: "method.reconcile-financial-statements.v5" as const, reference_date: input.referenceDate, unit: input.unit, state,
330	    block_reasons: blockReasons, incomplete_reasons: incompleteReasons, reconciliations, open_divergences: openDivergences, identities, uncovered_terms: uncovered,
331	  };
332	  const inputFingerprint = fingerprint(input);
333	  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint({...body, calculations, inputFingerprint})}};
334	}

